#!/bin/sh
# Fetch the images of docker-compose.yml by digest into images/ (generated by hvx/onboard/hydo-compose;
# hydo-build never pulls). Needs skopeo (or nix: nix build nixpkgs#skopeo).
set -eu
cd "$(dirname "$0")"
nix_skopeo() {
  for p in $(nix build --no-link --print-out-paths nixpkgs#skopeo); do
    [ -x "$p/bin/skopeo" ] && { echo "$p/bin/skopeo"; return; }
  done
  echo "fetch-images.sh: no skopeo" >&2; exit 1
}
SKOPEO=${SKOPEO:-$(command -v skopeo || nix_skopeo)}
POL=$(mktemp); trap 'rm -f "$POL"' EXIT
echo '{"default":[{"type":"insecureAcceptAnything"}]}' > "$POL"   # the digests pin the content
mkdir -p images
[ -d images/dockersamples-examplevotingapp_vote-latest-arm64-oci ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_vote@sha256:0ab82675962403d98735aa431ca116e8014051d5a8f145d302e04f21346f9b58 oci:images/dockersamples-examplevotingapp_vote-latest-arm64-oci:dockersamples/examplevotingapp_vote:latest
[ -f images/dockersamples-examplevotingapp_vote-latest-amd64.docker.tar ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_vote@sha256:e63c2cb6732d6e5026ec0c3ede7bd3052321068b91d30fa16561e0f334d807b8 docker-archive:images/dockersamples-examplevotingapp_vote-latest-amd64.docker.tar:dockersamples/examplevotingapp_vote:latest
[ -d images/dockersamples-examplevotingapp_result-latest-arm64-oci ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_result@sha256:c87f44054a409c8a457b19089efbb9bb039b4539af62b2f4906bf6f05d380c31 oci:images/dockersamples-examplevotingapp_result-latest-arm64-oci:dockersamples/examplevotingapp_result:latest
[ -f images/dockersamples-examplevotingapp_result-latest-amd64.docker.tar ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_result@sha256:7583fe9ceb85e658335e66d8d1f01c43b2bcdf9684f60e53f3989d6fc36a3bd0 docker-archive:images/dockersamples-examplevotingapp_result-latest-amd64.docker.tar:dockersamples/examplevotingapp_result:latest
[ -d images/dockersamples-examplevotingapp_worker-latest-arm64-oci ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_worker@sha256:374f13009def417269e568e3796746605a4efc4e166e7ccda69312face04b963 oci:images/dockersamples-examplevotingapp_worker-latest-arm64-oci:dockersamples/examplevotingapp_worker:latest
[ -f images/dockersamples-examplevotingapp_worker-latest-amd64.docker.tar ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/dockersamples/examplevotingapp_worker@sha256:8820615213ade73a83f930a90fffe4aa6c01865c2f277f2c9506e8a904a8ecbe docker-archive:images/dockersamples-examplevotingapp_worker-latest-amd64.docker.tar:dockersamples/examplevotingapp_worker:latest
[ -d images/redis-alpine-arm64-oci ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/library/redis@sha256:0819246a2bb1979f7745a8bae2559a2ffa49071ef7a5e7213b3e347e162aeb26 oci:images/redis-alpine-arm64-oci:redis:alpine
[ -f images/redis-alpine-amd64.docker.tar ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/library/redis@sha256:16b124a2d3eacd620d917ead6fd26cbf1f1d7117fa94122398971931cfe2d403 docker-archive:images/redis-alpine-amd64.docker.tar:redis:alpine
[ -d images/postgres-15-alpine-arm64-oci ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/library/postgres@sha256:188e422ad801eaf156d9b9e276064d931553a81f4281a18db98752178dbc061d oci:images/postgres-15-alpine-arm64-oci:postgres:15-alpine
[ -f images/postgres-15-alpine-amd64.docker.tar ] || "$SKOPEO" --policy "$POL" copy docker://docker.io/library/postgres@sha256:1d4031d6ed0a9b774b365f99a3c16127217eb19f699d8d43fc43b732748601ef docker-archive:images/postgres-15-alpine-amd64.docker.tar:postgres:15-alpine
ls -ld images/dockersamples-examplevotingapp_result-latest-amd64.docker.tar images/dockersamples-examplevotingapp_result-latest-arm64-oci images/dockersamples-examplevotingapp_vote-latest-amd64.docker.tar images/dockersamples-examplevotingapp_vote-latest-arm64-oci images/dockersamples-examplevotingapp_worker-latest-amd64.docker.tar images/dockersamples-examplevotingapp_worker-latest-arm64-oci images/postgres-15-alpine-amd64.docker.tar images/postgres-15-alpine-arm64-oci images/redis-alpine-amd64.docker.tar images/redis-alpine-arm64-oci
